const express = require('express');
const diagnostics_channel = require('node:diagnostics_channel');
const { AsyncLocalStorage } = require('node:async_hooks');
const { authMiddleware } = require('./auth');

const app = express();
const als = new AsyncLocalStorage();
const timingChannel = diagnostics_channel.channel('http:request:metrics');

const metricStore = new Map();

timingChannel.subscribe((metrics) => {
  const store = als.getStore();
  metricStore.set(metrics.requestId, {
    userId: store?.userId,
    cpuMicroseconds: metrics.cpuDelta,
    memoryRssDeltaBytes: metrics.memoryDelta,
    durationMs: metrics.duration
  });
});

app.use(authMiddleware);
app.use((req, res, next) => {
  als.run({ userId: req.user.id }, next);
});

app.get('/api/telemetry/requests/:requestId/metrics', (req, res) => {
  const metric = metricStore.get(req.params.requestId);
  if (!metric) {
    return res.status(404).json({ error: 'Metrics expired' });
  }

  // Ensure metrics belong to the requesting user
  if (metric.userId !== req.user.id) {
    return res.status(403).json({ error: 'Forbidden: metric data belongs to another user' });
  }

  res.json({
    requestId: req.params.requestId,
    durationMs: metric.durationMs,
    cpuMicroseconds: metric.cpuMicroseconds
  });
});

app.listen(9105);
